def pal_rgb(anch, n=256):
    xs = [a[0] for a in anch]
    out = []
    for k in range(n):
        ph = (k + 0.5) / n
        i = 0
        while i < len(xs) - 2 and xs[i + 1] <= ph:
            i += 1
        t = (ph - xs[i]) / (xs[i + 1] - xs[i])
        t = min(max((t - (1 - FRAC)) / FRAC, 0.0), 1.0)
        c0, c1 = anch[i][1], anch[i + 1][1]
        out.append(tuple(c0[j] * (1 - t) + c1[j] * t for j in range(3)))
    return out


def rgb_to_hw10(rgb):
    r, g, b = [c / 255.0 for c in rgb]
    y = 0.299 * r + 0.587 * g + 0.114 * b
    cb, cr = (b - y) / 1.772, (r - y) / 1.402
    return (round(64 + y * 876), round(512 + cr * 896), round(512 + cb * 896))


def prescale(yuv):
    y, u, v = yuv
    y = min(64 + round((y - 64) * 16 / 13), 940)
    return (y, min(max(u, 64), 960), min(max(v, 64), 960))


def pal_rom():
    vals = []
    for anch in (OIL, CON):
        for c in pal_rgb(anch):
            y, u, v = prescale(rgb_to_hw10(c))
            vals.append((y << 22) | (u << 12) | (v << 2))
    return vals


def map_rom(rows):
    vals = []
    for r in rows:
        for c in range(64):
            vals.append((int(r[3 * c:3 * c + 2], 16) << 4) | int(r[3 * c + 2], 16))
    return vals


def exp2_rom():
    return [min(round(32768 * 2 ** (i / 256)), 65535) for i in range(256)]


def vhd_table(name, depth, width, vals, slv=False):
    typ = "std_logic_vector" if slv else "unsigned"
    lines = ["    type t_%s is array (0 to %d) of %s(%d downto 0);" % (name.lower(), depth - 1, typ, width - 1),
             "    constant %s : t_%s := (" % (name, name.lower())]
    hexw = (width + 3) // 4
    items = []
    for v in vals:
        if width % 4 == 0:
            items.append('x"%0*X"' % (hexw, v))
        else:
            items.append('"%s"' % format(v, '0%db' % width))
    per = 16 if width % 4 == 0 else 8
    for i in range(0, len(items), per):
        lines.append("        " + ", ".join(items[i:i + per]) + ("," if i + per < len(items) else ""))
    lines.append("    );")
    return "\n".join(lines)


def main():
    up = map_rom(MAP_UP)
    lo = map_rom(MAP_LO)
    assert len(up) == 4096 and len(lo) == 2048
    body = [
        "-- Generated by oilslick.py -- DO NOT EDIT.",
        "library ieee;", "use ieee.std_logic_1164.all;", "use ieee.numeric_std.all;", "",
        "package oilslick_pkg is",
        vhd_table("C_OS_MAPU", 4096, 10, up),
        vhd_table("C_OS_MAPL", 2048, 10, lo),
        vhd_table("C_OS_PAL", 512, 32, pal_rom(), slv=True),
        vhd_table("C_OS_EXP2", 256, 16, exp2_rom()),
        "end package oilslick_pkg;", ""]
    with open(os.path.join(HERE, "oilslick_pkg.vhd"), "w") as f:
        f.write("\n".join(body))


if __name__ == "__main__":
    main()
